:root {
  --ink: #1c1f22;
  --ink-soft: #5c646b;
  --line: #d8dde1;
  --surface: #ffffff;
  --accent: #3d7a4f;
  --focus: #1b56c4;
  --bg: #f7f8f9;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color: var(--ink);
  background: var(--bg);
  line-height: 1.55;
}

a { color: var(--ink); }

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.page {
  max-width: 1080px;
  margin: 0 auto;
  padding: 0 20px 48px;
}

.site-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 0 12px;
  border-bottom: 1px solid var(--line);
  background: var(--bg);
}

.store-name { margin: 0; font-size: 1.4rem; font-weight: 700; }
.store-name a { text-decoration: none; }
.cart-link { text-decoration: none; font-weight: 600; }

.breadcrumb { padding: 14px 0; }
.breadcrumb ol {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  list-style: none;
  margin: 0;
  padding: 0;
  font-size: 0.95rem;
  color: var(--ink-soft);
}
.breadcrumb li + li::before { content: "›"; margin-right: 8px; color: var(--ink-soft); }
.breadcrumb a { color: var(--ink-soft); }
.breadcrumb [aria-current="page"] { color: var(--ink); font-weight: 600; }

.product {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(320px, 1fr);
  gap: 36px;
  align-items: start;
}

.carousel {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 16px;
}
.carousel-stage { overflow: hidden; border-radius: 8px; }
.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 12px;
  color: var(--ink-soft);
}

.product-info h1 { margin: 0 0 4px; font-size: 1.9rem; }
.tagline { margin: 0 0 8px; color: var(--ink-soft); }
.rating { margin: 0 0 12px; color: var(--ink-soft); }
.rating [aria-hidden] { color: #c8862a; letter-spacing: 2px; }

.price { display: flex; align-items: center; gap: 8px; margin: 0 0 18px; }
.price-value { font-size: 1.4rem; font-weight: 700; }

.tooltip { position: relative; display: inline-block; }
.tooltip-trigger {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: 1px solid var(--line);
  background: var(--surface);
  cursor: help;
  font-style: italic;
  font-family: Georgia, serif;
  line-height: 1;
}
.tooltip-text {
  position: absolute;
  bottom: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%);
  width: max-content;
  max-width: 220px;
  padding: 8px 10px;
  background: #1c1f22;
  color: #fff;
  border-radius: 6px;
  font-size: 0.85rem;
  visibility: hidden;
  opacity: 0;
  transition: opacity 120ms ease;
  z-index: 5;
}
.tooltip-text.is-open { visibility: visible; opacity: 1; }

.colors { border: 0; margin: 0 0 18px; padding: 0; }
.colors legend { font-weight: 600; margin-bottom: 8px; padding: 0; }
.colors input { position: absolute; opacity: 0; pointer-events: none; }
.swatch {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  border-radius: 50%;
  margin-right: 10px;
  border: 2px solid transparent;
  cursor: pointer;
}
.swatch-dot { width: 28px; height: 28px; border-radius: 50%; border: 1px solid rgba(0,0,0,0.2); }
.swatch-dot[data-color="blue"] { background: #2b5d8c; }
.swatch-dot[data-color="black"] { background: #22252b; }
.swatch-dot[data-color="grey"] { background: #8d8d8d; }
.swatch:focus-within { outline: 3px solid var(--focus); outline-offset: 2px; }
.swatch.is-selected { border-color: var(--ink); }

.size-row { display: flex; align-items: flex-start; gap: 16px; margin: 0 0 14px; }
.field { flex: 1; }
.field label, .field-label { display: block; font-weight: 600; margin-bottom: 6px; }
select, input[type="number"] {
  font: inherit;
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--surface);
  max-width: 100%;
}
.link-button {
  background: none;
  border: 0;
  padding: 0;
  margin-top: 26px;
  color: var(--ink);
  text-decoration: underline;
  cursor: pointer;
  font: inherit;
}
.hint { margin: 6px 0 0; font-size: 0.85rem; color: var(--ink-soft); }
.error { margin: 6px 0 0; color: #a5231d; font-weight: 600; }

.quantity-row { display: flex; align-items: flex-start; gap: 16px; margin: 0 0 20px; }
.stepper { display: flex; align-items: stretch; gap: 4px; }
.stepper button {
  width: 38px;
  font-size: 1.2rem;
  border: 1px solid var(--line);
  background: var(--surface);
  border-radius: 6px;
  cursor: pointer;
}
.stepper button:disabled { color: #b6bcc1; cursor: not-allowed; }
.stepper input { width: 70px; text-align: center; }

.actions { display: flex; align-items: center; gap: 12px; }
button.primary, .dialog-actions button[type="submit"] {
  background: var(--accent);
  color: #fff;
  border: 1px solid var(--accent);
  border-radius: 6px;
  padding: 12px 22px;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}
button.secondary {
  background: var(--surface);
  color: var(--ink);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 8px 14px;
  font: inherit;
  cursor: pointer;
}
.heart {
  width: 46px;
  height: 46px;
  font-size: 1.3rem;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: var(--surface);
  cursor: pointer;
}
.heart[aria-pressed="true"] { color: #c22b4f; }
.confirmation { min-height: 24px; margin: 10px 0 0; color: var(--accent); font-weight: 600; }

.features { margin: 22px 0 0; padding-left: 20px; color: var(--ink-soft); }

.tabs { margin: 48px 0 0; }
.tablist { display: flex; gap: 8px; border-bottom: 1px solid var(--line); flex-wrap: wrap; }
.tab {
  padding: 10px 16px;
  border: 1px solid transparent;
  border-bottom: 0;
  background: none;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
  border-radius: 6px 6px 0 0;
}
.tab.is-selected { background: var(--surface); border-color: var(--line); }
[role="tabpanel"] { border: 1px solid var(--line); border-top: 0; background: var(--surface); padding: 18px 20px; border-radius: 0 0 8px 8px; }
[role="tabpanel"] h2 { margin-top: 0; }
[role="tabpanel"] blockquote { margin: 0 0 12px; color: var(--ink-soft); }

.questions { margin: 48px 0 0; }
.questions h2 { margin: 0 0 12px; }
.question { border: 1px solid var(--line); border-radius: 8px; background: var(--surface); margin-bottom: 10px; }
.question h3 { margin: 0; font-size: 1.05rem; }
.question-trigger {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
  padding: 14px 16px;
  background: none;
  border: 0;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.question-trigger span:last-child { color: var(--ink-soft); }
.question [role="region"] { padding: 0 16px 14px; }
.question [role="region"] p { margin: 0; }

.dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(20, 22, 25, 0.55);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 20;
}
.dialog {
  background: var(--surface);
  border-radius: 10px;
  padding: 24px;
  width: min(440px, 100%);
  box-shadow: 0 18px 45px rgba(0, 0, 0, 0.25);
}
.dialog h2 { margin-top: 0; }
.units { border: 1px solid var(--line); border-radius: 6px; margin: 12px 0; padding: 10px 12px; }
.units legend { font-weight: 600; padding: 0 4px; }
.size-guide-result { font-weight: 600; color: var(--accent); }
.dialog-actions { display: flex; gap: 10px; margin-top: 14px; }

.site-footer {
  margin-top: 56px;
  padding-top: 24px;
  border-top: 1px solid var(--line);
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 24px;
  color: var(--ink-soft);
}
.site-footer h2 { font-size: 1rem; margin: 0 0 8px; color: var(--ink); }
.site-footer ul { list-style: none; margin: 0; padding: 0; }
.site-footer a { color: var(--ink-soft); }
.social li { display: inline-block; margin-right: 14px; }

@media (max-width: 820px) {
  .product { grid-template-columns: 1fr; }
  .site-footer { grid-template-columns: 1fr; }
}
