.hint { margin: 6px 0 0; font-size: 0.85rem; color: var(--ink-soft); }
.error { margin: 6px 0 0; color: #a5231d; font-weight: 600; }

.quantity-row { display: flex; align-items: flex-start; gap: 16px; margin: 0 0 20px; }
.stepper { display: flex; align-items: stretch; gap: 4px; }
.stepper button {
  width: 38px;
  font-size: 1.2rem;
  border: 1px solid var(--line);
  background: var(--surface);
  border-radius: 6px;
  cursor: pointer;
}
.stepper button:disabled { color: #b6bcc1; cursor: not-allowed; }
.stepper input { width: 70px; text-align: center; }

.actions { display: flex; align-items: center; gap: 12px; }
button.primary, .dialog-actions button[type="submit"] {
  background: var(--accent);
  color: #fff;
  border: 1px solid var(--accent);
  border-radius: 6px;
  padding: 12px 22px;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}
button.secondary {
  background: var(--surface);
  color: var(--ink);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 8px 14px;
  font: inherit;
  cursor: pointer;
}
.heart {
  width: 46px;
  height: 46px;
  font-size: 1.3rem;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: var(--surface);
  cursor: pointer;
}
.heart[aria-pressed="true"] { color: #c22b4f; }
.confirmation { min-height: 24px; margin: 10px 0 0; color: var(--accent); font-weight: 600; }

.features { margin: 22px 0 0; padding-left: 20px; color: var(--ink-soft); }

.tabs { margin: 48px 0 0; }
.tablist { display: flex; gap: 8px; border-bottom: 1px solid var(--line); flex-wrap: wrap; }
.tab {
  padding: 10px 16px;
  border: 1px solid transparent;
  border-bottom: 0;
  background: none;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
  border-radius: 6px 6px 0 0;
}
.tab.is-selected { background: var(--surface); border-color: var(--line); }
[role="tabpanel"] { border: 1px solid var(--line); border-top: 0; background: var(--surface); padding: 18px 20px; border-radius: 0 0 8px 8px; }
[role="tabpanel"] h2 { margin-top: 0; }
[role="tabpanel"] blockquote { margin: 0 0 12px; color: var(--ink-soft); }

.questions { margin: 48px 0 0; }
.questions h2 { margin: 0 0 12px; }
.question { border: 1px solid var(--line); border-radius: 8px; background: var(--surface); margin-bottom: 10px; }
.question h3 { margin: 0; font-size: 1.05rem; }
.question-trigger {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
  padding: 14px 16px;
  background: none;
  border: 0;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.question-trigger span:last-child { color: var(--ink-soft); }
.question [role="region"] { padding: 0 16px 14px; }
.question [role="region"] p { margin: 0; }

.dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(20, 22, 25, 0.55);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 20;
}
.dialog {
  background: var(--surface);
  border-radius: 10px;
  padding: 24px;
  width: min(440px, 100%);
  box-shadow: 0 18px 45px rgba(0, 0, 0, 0.25);
}
.dialog h2 { margin-top: 0; }
.units { border: 1px solid var(--line); border-radius: 6px; margin: 12px 0; padding: 10px 12px; }
.units legend { font-weight: 600; padding: 0 4px; }
.size-guide-result { font-weight: 600; color: var(--accent); }
.dialog-actions { display: flex; gap: 10px; margin-top: 14px; }

.site-footer {
  margin-top: 56px;
  padding-top: 24px;
  border-top: 1px solid var(--line);
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 24px;
  color: var(--ink-soft);
}
.site-footer h2 { font-size: 1rem; margin: 0 0 8px; color: var(--ink); }
.site-footer ul { list-style: none; margin: 0; padding: 0; }
.site-footer a { color: var(--ink-soft); }
.social li { display: inline-block; margin-right: 14px; }

@media (max-width: 820px) {
  .product { grid-template-columns: 1fr; }
  .site-footer { grid-template-columns: 1fr; }
}
